insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_17_v1'
from (values
('127.105.d.1.A',3,'A first-year drafting student realizes a lesson on scale is confusing. The best step is to:','["Ask the teacher for help early", "Wait until the test", "Skip the lesson", "Copy a classmate''s sheet"]'::jsonb,0,'Self-monitoring means seeking help early.','original'),
('127.105.d.1.A',4,'A student tracks which drafting skills feel weak and plans extra practice. This habit is called:','["Guessing", "Self-monitoring learning needs", "Avoiding feedback", "Procrastinating"]'::jsonb,1,'Tracking needs guides improvement.','original'),
('127.105.d.1.B',3,'Which habit best helps a student manage studio assignments and deadlines?','["Ignoring due dates", "Starting the night before", "Keeping a planner of due dates", "Working with no plan"]'::jsonb,2,'Planning supports academic success.','original'),
('127.105.d.1.B',4,'Setting aside the same time each day for studio work builds:','["A schedule gap", "Extra deadlines", "Random effort", "A study routine"]'::jsonb,3,'Routine supports consistent progress.','original'),
('127.105.d.1.C',3,'In drafting, accuracy means a line is:','["Placed exactly where it belongs", "Drawn quickly", "Drawn lightly", "Drawn in color"]'::jsonb,0,'Accuracy is correct placement.','original'),
('127.105.d.1.C',4,'Precision in a dimension string means measurements are:','["Left off", "Consistent to the required detail", "Estimated", "Rounded wildly"]'::jsonb,1,'Precision means consistent exactness.','original'),
('127.105.d.1.D',3,'A designer who finishes every sheet on a plan before moving on shows:','["Delay", "Avoidance", "Task mastery and completion", "Poor planning"]'::jsonb,2,'Completion is a work habit.','original'),
('127.105.d.1.D',4,'Which is the best way to master a new drafting skill?','["Try it once", "Watch only", "Skip hard parts", "Practice it until it is accurate and repeatable"]'::jsonb,3,'Mastery requires repeated practice.','original'),
('127.105.d.1.E',3,'A designer explains a floor plan to a client using clear words and a sketch. This shows:','["Effective communication", "Avoiding clients", "Hiding details", "Poor listening"]'::jsonb,0,'Verbal and visual clarity.','original'),
('127.105.d.1.E',4,'A written design summary should be organized so that the reader can:','["Skip it", "Find key decisions quickly", "Ignore dates", "Guess the plan"]'::jsonb,1,'Clear writing saves time.','original'),
('127.105.d.1.F',3,'A work order for a design change lists the task, date, and:','["Lunch order", "Weather", "The person responsible", "Favorite color"]'::jsonb,2,'Work orders assign responsibility.','original'),
('127.105.d.1.F',4,'Completing paperwork on time helps a design office to:','["Avoid billing", "Waste time", "Hide errors", "Track changes and costs"]'::jsonb,3,'Paperwork documents the job.','original'),
('127.105.d.1.G',3,'Before estimating a job, an architectural drafter checks local:','["Legal and code restrictions", "Sports schedules", "Menu choices", "Fashion trends"]'::jsonb,0,'Legal limits affect cost and schedule.','original'),
('127.105.d.1.G',4,'A zoning limit on building height most directly affects the estimate of:','["Paint brands", "Design options and materials", "Parking tickets", "Employee birthdays"]'::jsonb,1,'Limits shape what can be built.','original'),
('127.105.d.1.H',3,'A drafter reads a set of blueprints to find:','["Movie times", "Menus", "Dimensions, symbols, and notes", "Song lyrics"]'::jsonb,2,'Blueprints carry the information.','original'),
('127.105.d.1.H',4,'A section symbol on a plan tells the reader where the building is:','["Sold", "Insured", "Painted", "Cut for a section view"]'::jsonb,3,'Cut lines show the section location.','original'),
('127.105.d.1.I',3,'An auxiliary view is used to show a surface that is:','["Slanted and not shown true in standard views", "Flat and in front", "Hidden by paint", "Too small to see"]'::jsonb,0,'Auxiliary views show true shape.','original'),
('127.105.d.1.I',4,'Revolving an object in descriptive geometry helps to find its:','["Color", "True length or shape", "Price", "Weight"]'::jsonb,1,'Revolution shows true size.','original'),
('127.105.d.2.A',3,'Balance, rhythm, and proportion are examples of architectural:','["Tax rules", "Zoning laws", "Design principles", "Safety codes"]'::jsonb,2,'These principles guide good design.','original'),
('127.105.d.2.A',4,'Repeating window shapes along a facade shows the principle of:','["Chaos", "Contrast only", "Hierarchy only", "Rhythm"]'::jsonb,3,'Repetition creates rhythm.','original'),
('127.105.d.2.B',3,'Zoning codes control how land can be:','["Used and built on", "Photographed", "Named", "Taxed only"]'::jsonb,0,'Zoning sets use and form.','original'),
('127.105.d.2.B',4,'A setback requirement tells a designer how far a building must be from:','["The moon", "The property line", "The roof", "The kitchen"]'::jsonb,1,'Setbacks keep distance.','original'),
('127.105.d.2.C',3,'Construction types are classified by what a building is made of and its:','["Name", "Paint", "Fire resistance", "Mailbox"]'::jsonb,2,'Types relate to fire ratings.','original'),
('127.105.d.2.C',4,'A steel-framed building is usually classified differently than wood-framed because of its:','["Door count", "Garden", "Address", "Materials and fire performance"]'::jsonb,3,'Material affects classification.','original'),
('127.105.d.3.A',3,'Tools for architectural drafting include a scale, triangle, and:','["Compass", "Whisk", "Trowel", "Saw blade"]'::jsonb,0,'Hand drafting needs drawing tools.','original'),
('127.105.d.3.B',3,'Used solvents and cleaners from a shop should be:','["Burned outdoors", "Disposed of following safety rules", "Poured into drains", "Left open"]'::jsonb,1,'Hazardous materials need proper disposal.','original'),
('127.105.d.3.B',4,'Where can a worker find disposal information for a product?','["On a score sheet", "On a menu", "On its Safety Data Sheet", "On a receipt"]'::jsonb,2,'SDS covers disposal.','original'),
('127.105.d.3.C',3,'New technologies that may affect architecture include building information modeling and:','["Candle making", "Quill writing", "Typewriting", "3D printing"]'::jsonb,3,'Emerging tools change the field.','original'),
('127.105.d.3.C',4,'BIM software helps teams to:','["Share a coordinated 3D building model", "Avoid planning", "Remove drawings", "Print menus"]'::jsonb,0,'BIM coordinates data.','original'),
('127.105.d.4.A',3,'The first step in solving a design problem is to:','["Pick a color", "Analyze the situation and name the problem", "Skip research", "Start building"]'::jsonb,1,'Problem solving begins with identification.','original'),
('127.105.d.4.A',4,'Writing a design problem statement before sketching helps to:','["Replace research", "Delay all work", "Keep solutions focused", "Create confusion"]'::jsonb,2,'Statements focus design.','original'),
('127.105.d.4.B',3,'Breaking a large house design into rooms and systems makes it easier to:','["Avoid choices", "Ignore details", "Skip planning", "Analyze each part"]'::jsonb,3,'Divide to solve.','original'),
('127.105.d.4.B',4,'A designer lists structure, circulation, and light as separate parts of a complex project. This is:','["Decomposition", "Copying", "Guessing", "Hiding problems"]'::jsonb,0,'Splitting a problem into parts.','original'),
('127.105.d.4.C',3,'A drawing with cleanly joined lines and correct dimensions shows careful:','["Improvisation", "Accuracy and precision", "Speed only", "Luck"]'::jsonb,1,'Good drafting is accurate.','original'),
('127.105.d.4.C',4,'Checking dimensions against the program before plotting is a way to:','["Skip quality", "Avoid review", "Catch errors early", "Create errors"]'::jsonb,2,'Checks prevent rework.','original'),
('127.105.d.4.D',3,'A student who completes a sketch without help is:','["Avoiding work", "Working collaboratively", "Cheating", "Working independently"]'::jsonb,3,'Independent work builds skill.','original'),
('127.105.d.4.D',4,'Working independently on a design requires:','["Self-direction and time management", "Group votes", "No planning", "Constant supervision"]'::jsonb,0,'Independence takes planning.','original'),
('127.105.d.4.E',3,'A team of students splits drafting tasks and reviews each other''s drawings. This is:','["Copying", "Collaboration", "Isolation", "Competition only"]'::jsonb,1,'Collaboration shares work.','original'),
('127.105.d.4.E',4,'A key strength of collaboration on a design team is:','["Hiding mistakes", "Slower meetings only", "Combining different ideas and skills", "Fewer drawings"]'::jsonb,2,'Teams combine strengths.','original'),
('127.105.d.4.F',3,'Before designing a library, a student studies similar buildings. This step is:','["Demolition", "Cost cutting", "Final plotting", "Project research"]'::jsonb,3,'Research informs design.','original'),
('127.105.d.4.F',4,'Which source helps most when researching a historic site design?','["Local records and site measurements", "Random ads", "Fiction novels", "Rumors"]'::jsonb,0,'Reliable sources guide design.','original'),
('127.105.d.4.G',3,'A strong presentation of an architectural product has clear drawings and:','["Hidden notes", "A clear explanation", "No labels", "Tiny text"]'::jsonb,1,'Presenting needs clarity.','original'),
('127.105.d.4.G',4,'A design is effective when it meets the client''s needs and:','["No budget", "No code", "The project constraints", "Only the designer''s taste"]'::jsonb,2,'Design meets needs and limits.','original'),
('127.105.d.4.H',3,'A critique of a final design should be treated as:','["Wasted time", "An insult", "A grade only", "Feedback for improvement"]'::jsonb,3,'Feedback improves work.','original'),
('127.105.d.4.H',4,'After a critique, the best response is to:','["Revise the design using the useful comments", "Argue every point", "Discard the project", "Ignore all notes"]'::jsonb,0,'Use feedback.','original'),
('127.105.d.4.I',3,'Architectural lettering should be:','["Tiny and faint", "Neat, uniform, and readable", "Random in size", "Fancy only"]'::jsonb,1,'Lettering communicates.','original'),
('127.105.d.4.I',4,'Light guidelines are used for lettering so that the letters are:','["Colored", "Crooked", "Even in height", "Hidden"]'::jsonb,2,'Guidelines keep height uniform.','original'),
('127.105.d.4.J',3,'Preliminary sketches are used to:','["Replace plans", "Print the set", "Finish the project", "Explore ideas before drafting"]'::jsonb,3,'Sketches explore options.','original'),
('127.105.d.4.J',4,'A bubble diagram in early residential design shows:','["Room relationships", "Wall thickness", "Electrical loads", "Roof pitch"]'::jsonb,0,'Bubbles relate spaces.','original'),
('127.105.d.4.K',3,'Traditional technical drafting uses tools such as a T-square and:','["Spoons", "Triangles", "Brushes only", "Mallets"]'::jsonb,1,'Hand drafting uses straightedges.','original'),
('127.105.d.4.K',4,'A drafter uses a T-square against the drawing board''s edge to draw:','["Freehand shapes", "Curves", "Parallel horizontal lines", "Circles"]'::jsonb,2,'T-squares guide horizontals.','original'),
('127.105.d.4.L',3,'Efficient use of space in a floor plan means rooms are arranged to:','["Add hallways", "Avoid windows", "Block doors", "Reduce wasted area and movement"]'::jsonb,3,'Efficient layouts save space.','original'),
('127.105.d.4.L',4,'Placing the kitchen near the dining room improves:','["Circulation and function", "Roof strength", "Paint color", "Soil quality"]'::jsonb,0,'Adjacent related spaces help function.','original'),
('127.105.d.4.M',3,'Orientation of a building on its site considers sun, wind, and:','["Cars only", "Views and access", "Phone signal", "Lunch"]'::jsonb,1,'Orientation uses site conditions.','original'),
('127.105.d.4.M',4,'In a hot climate, large windows facing west can cause:','["No light", "Damp walls", "Excess heat gain in the afternoon", "Cooler rooms"]'::jsonb,2,'West sun is hot.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
