('127.105.d.9.D',4,'Digital portfolios may include drawings, photos, and:','["Passwords", "Bank data", "Reflections on each project", "Receipts"]'::jsonb,2,'Reflections add context.','original'),
('127.105.d.9.E',3,'A professional resume lists education, skills, and:','["Home videos", "Favorite foods", "Passwords", "Work experience"]'::jsonb,3,'Resumes present qualifications.','original'),
('127.105.d.9.E',4,'A resume for an architectural internship should highlight:','["Relevant skills such as CAD and drafting", "Opinions of friends", "Unrelated hobbies only", "Blank space"]'::jsonb,0,'Relevant skills matter.','original'),
